import java.io.*;
import java.util.*;

class Solution {
    public int[] finalPrices(int[] prices) {
        int[] answer = prices.clone();
        int[] stack = new int[prices.length];
        int top = 0;

        for (int i = 0; i < prices.length; i++) {
            while (top > 0 && prices[stack[top - 1]] >= prices[i]) {
                int j = stack[--top];
                answer[j] -= prices[i];
            }
            stack[top++] = i;
        }

        return answer;
    }
}

