#include <bits/stdc++.h>
using namespace std;

class Solution {
public:
    vector<int> finalPrices(const vector<int>& prices) {
        vector<int> answer = prices;
        vector<int> stack;
        stack.reserve(prices.size());

        for (int i = 0; i < static_cast<int>(prices.size()); ++i) {
            while (!stack.empty() && prices[stack.back()] >= prices[i]) {
                int j = stack.back();
                stack.pop_back();
                answer[j] -= prices[i];
            }
            stack.push_back(i);
        }

        return answer;
    }
};

