#include <stdio.h>
#include <stdlib.h>

int* finalPrices(int* prices, int pricesSize, int* returnSize) {
    int* answer = (int*)malloc((size_t)pricesSize * sizeof(int));
    int* stack = (int*)malloc((size_t)pricesSize * sizeof(int));

    if (answer == NULL || stack == NULL) {
        free(answer);
        free(stack);
        *returnSize = 0;
        return NULL;
    }

    for (int i = 0; i < pricesSize; ++i) {
        answer[i] = prices[i];
    }

    int top = 0;

    for (int i = 0; i < pricesSize; ++i) {
        while (top > 0 && prices[stack[top - 1]] >= prices[i]) {
            int j = stack[--top];
            answer[j] -= prices[i];
        }
        stack[top++] = i;
    }

    free(stack);
    *returnSize = pricesSize;
    return answer;
}

